p = p.replace(o1, n1).replace(o2, n2)
p = p.replace("`D:\_claude_work\RMC\kzh\kz30_views.cs → kz31_annot.cs → kz33_tables.cs → kz34_layout.cs → kz36_show.cs`.", "`D:\_claude_work\RMC\kzh\kzh_gen.py → kz02_rebar.cs (скоба: kz44_skoba.cs) → kz30_views.cs → kz31_annot.cs → kz33_tables.cs → kz34_layout.cs → kz36_show.cs`.")
